// Watchlist each spraying source as a business event (event.type = ad.watchlist.add).
// Dashboards and later runs can query it: fetch bizevents | filter event.type == "ad.watchlist.add"
import { execution } from '@dynatrace-sdk/automation-utils';
import { businessEventsClient } from '@dynatrace-sdk/client-classic-environment-v2';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const { records } = await ex.result('detect_password_spray');
  if (!records?.length) return { watchlisted: 0 };

  const events = records.map((r) => ({
    'event.provider': 'ad-risky-accounts-workflow',
    'event.type': 'ad.watchlist.add',
    'watchlist.reason': 'password_spray',
    'source.ip': r.source,
    'spray.accounts': Number(r.accounts),
    'spray.failures': Number(r.failures),
    'spray.sample_accounts': (r.sample_accounts || []).join(', '),
    'workflow.execution_id': executionId,
  }));
  await businessEventsClient.ingest({ body: events, type: 'application/json' });
  return { watchlisted: events.length, sources: records.map((r) => r.source) };
}

// Look for an approved ServiceNow change in "Implement" state that mentions the member being added.
// Never fails the workflow: with no credential or no reachable ServiceNow it reports "NOT CHECKED",
// so the page still goes out.
import { execution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient } from '@dynatrace-sdk/client-classic-environment-v2';

const SNOW_INSTANCE = 'https://YOUR_INSTANCE.service-now.com';   // also add to Settings > External requests
const CREDENTIAL_ID = 'CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX';     // user/password credential, scope: App Engine

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const { records } = await ex.result('detect_privileged_group_change');

  let auth = null;
  try {
    const c = await credentialVaultClient.getCredentialsDetails({ id: CREDENTIAL_ID });
    auth = 'Basic ' + btoa(`${c.username}:${c.password}`);
  } catch (e) {
    console.log('ServiceNow credential not available: ' + e);
  }

  const changes = [];
  for (const r of records) {
    let status = 'NOT CHECKED';
    if (auth) {
      try {
        const q = encodeURIComponent(`state=-1^short_descriptionLIKE${r.member}^ORdescriptionLIKE${r.member}`);
        const url = `${SNOW_INSTANCE}/api/now/table/change_request?sysparm_query=${q}` +
                    '&sysparm_fields=number,short_description&sysparm_limit=5';
        const res = await fetch(url, { headers: { Authorization: auth, Accept: 'application/json' } });
        if (res.ok) {
          const found = (await res.json()).result || [];
          status = found.length ? found.map((c) => c.number).join(', ') : 'NO APPROVED CHANGE';
        } else {
          console.log(`ServiceNow returned ${res.status}`);
        }
      } catch (e) {
        console.log('ServiceNow lookup failed: ' + e);
      }
    }
    changes.push({ ...r, change: status });
  }
  return { changes, without_change: changes.filter((c) => c.change === 'NO APPROVED CHANGE').length };
}

